import socket
import sys
import os
import time
"""
HexByteConversion

Convert a byte string to it's hex representation for output or visa versa.

ByteToHex converts byte string "\xFF\xFE\x00\x01" to the string "FF FE 00 01"
HexToByte converts string "FF FE 00 01" to the byte string "\xFF\xFE\x00\x01"
"""

# -------------------------------------------------------------------------------


def ByteToHex(byteStr):
    """
    Convert a byte string to it's hex string representation e.g. for output.
    """
    # Uses list comprehension which is a fractionally faster implementation than
    # the alternative, more readable, implementation below
    #    hex = []
    #    for aChar in byteStr:
    #        hex.append( "%02X " % ord( aChar ) )
    #    return ''.join( hex ).strip()

    return ''.join(["%02X " % ord(x) for x in byteStr]).strip()

# -------------------------------------------------------------------------------


def HexToByte(hexStr):
    """
    Convert a string hex byte values into a byte string. The Hex Byte values may
    or may not be space separated.
    """
    # The list comprehension implementation is fractionally slower in this case
    #    hexStr = ''.join( hexStr.split(" ") )
    #    return ''.join( ["%c" % chr( int ( hexStr[i:i+2],16 ) ) \
    #                                   for i in range(0, len( hexStr ), 2) ] )

    bytes = []

    hexStr = ''.join(hexStr.split(" "))

    for i in range(0, len(hexStr), 2):
        bytes.append(chr(int(hexStr[i:i + 2], 16)))
    # print hexStr
    return ''.join(bytes)


# -------------------------------------------------------------------------------

def get_nid_prefix_for_cmd(nid):
    hex_string = hex(int(nid, base=16))
    hex_string = hex_string.upper()
    return hex_string[2:]  # remove 0x prefix


def startBrowserCPU(s, nid):

    nid_1 = nid[:2]
    number = nid[2:3]

    for cpu in range(8):
        cmd = "00 00 1B E4 %s %00d 12 00 10 11 03 08 00 14 00 00 00 00 00 64" % (get_nid_prefix_for_cmd(nid_1),
                                                                                 cpu + (int(number) * 10) + 1)
        data = HexToByte(cmd)
        time.sleep(0.1)
        try:
            s.send(data)
        except Exception:
            print("send failed: maybe connection is currently used by LTEBrowser")  # noqa: T201


def stopBrowserCPU(s, nid):

    nid_1 = nid[:2]
    number = nid[2:3]

    for cpu in range(8):
        cmd = "00 00 1B E6 %s %00d 12 00 10 11 03 08 00 14 00 00 00 00 00 00" % (get_nid_prefix_for_cmd(nid_1),
                                                                                 cpu + (int(number) * 10) + 1)
        data = HexToByte(cmd)

        time.sleep(0.1)
        try:
            s.send(data)
        except Exception:
            print("send failed: maybe connection is currently used by LTEBrowser")  # noqa: T201


def getCpuVersions(s, nid):

    cpu_table = [-1, -1, -1, -1, -1, -1, -1, -1]

    nid_1 = nid[:2]
    nid_2 = nid[2:4]
    number = nid[2:3]

    for test in range(1):
        for cpu in range(8):
            cmd = "00 00 1B E6 %s %00d 12 00 10 11 03 08 00 14 00 00 00 00 00 00" % (get_nid_prefix_for_cmd(nid_1),
                                                                                     cpu + (int(number) * 10) + 1)
            req = "00 00 1B E7 %s %s 04 CF %s" % (get_nid_prefix_for_cmd(nid_1), nid_2, get_nid_prefix_for_cmd(nid_1))
            data = HexToByte(cmd)

            try:
                s.send(data)
            except Exception:
                print("send failed: maybe connection is currently used by LTEBrowser")  # noqa: T201
                return cpu_table

            try:
                chunk = s.recv(1024)
            except Exception:
                print("No answer")  # noqa: T201
                continue

            msg_str = " "
            msg_str = ByteToHex(chunk)
            # cpu table is processed in this function
            process_cpu_message(cpu_table, msg_str, number, req)

    return cpu_table


def process_cpu_message(cpu_table, msg_str, number, req):
    while 1:
        msg_status = -1
        msg_status = msg_str.find(req)
        if msg_status == -1:

            break
        else:
            msg_status += 12
            tmpcpu = msg_str[msg_status + 15:msg_status + 17].split()
            tmpcpu = tmpcpu[0]
            cpu = int(tmpcpu, 10) - ((int(number) * 10) + 1)

            tmpCPULoad = msg_str[msg_status + 36:msg_status + 47].split()
            tmpCPULoad = tmpCPULoad[1] + tmpCPULoad[0]

            CPULoad = tmpCPULoad.strip()
            CPULoad = float(int(CPULoad, 16)) / 100
            msg_str = msg_str[msg_status + 47:]
            cpu_table[cpu] = CPULoad


def PrintFormatedOutputToConsole(table):
    print("")  # noqa: T201
    print("Get CPU Loads for all DSPs on KEPLER...")  # noqa: T201
    print("")  # noqa: T201
    print("FSP")  # noqa: T201
    print("| DSP")  # noqa: T201
    print("| | CORE")  # noqa: T201
    print("| | |     LOAD")  # noqa: T201
    print("-----------------------------------------------------------------------")  # noqa: T201

    for fsp in range(1):
        for cpu in range(8):
            print("%d %d %d:" % (fsp + 1, cpu + 1, 1)),  # noqa: T201
            if table[cpu] == -1:
                print("No answer") # noqa: T201
            else:
                print("%7.2f " % table[cpu], "%")  # noqa: T201


sleeptime = 10  # default refresh time in seconds


def main(s, nid):

    startBrowserCPU(s, nid)

    while 1:
        os.system('CLS')
        try:
            TabCPULoad = getCpuVersions(s, nid)
            PrintFormatedOutputToConsole(TabCPULoad)
            t = time.localtime()
            print("\r\n%02i.%02i.%02i %02i:%02i:%02i " % (t[0:6]))  # noqa: T201
            print("update every %i s. Press ^C to exit" % (sleeptime))  # noqa: T201
            time.sleep(sleeptime)
        except Exception:
            print("Aborted")  # noqa: T201
            stopBrowserCPU(s, nid)
            s.close()
            sys.exit()


s = socket.socket(
    socket.AF_INET, socket.SOCK_STREAM)
s.settimeout(10)
try:
    s.connect((sys.argv[2], 15002))
except Exception:
    print("connect failed: maybe connection is currently used by LTEBrowser")  # noqa: T201
    s.close()
    exit()
s.settimeout(0.8)
main(s, sys.argv[1])
stopBrowserCPU(s, sys.argv[1])
s.close()
